import {num} from './ui.mjs';
const examples=[
 {id:'self',title:'样例一 · 自评估曲线（原图）',image:'sec-pdp-self-evaluation.png',q:143150,d:.08,
 annotations:'图中文字：2017年起始点155542吨/月；2018年起始点143150吨/月；曲线类型EXPONENTIAL（指数）；递减8.00%。图中模型栏起始日期为2019-01-01，与红色起始点文字存在年份口径差异，待原报告核实。',
 petroleum:'两个标注起点相差−7.97%，与图中8%递减量级接近，但不是同一预测期的实际偏差检验。绿色总产油、品红平均产油、蓝色产水及黄色井数需要分轴解读；产水与产油量级变化只能提示水驱和生产制度核查方向，不能由图直接判定水窜或压力亏空。',
 conclusion:'先核对2018/2019起算日期、单井平均口径、开井时长和计量，再在稳定生产段验证8%指数递减。若实际连续低于冻结基准，逐井排查停井与高含水贡献，确认原因后比选恢复生产、分层控水或注采调整。'},
 {id:'decline',title:'样例二 · 动态法SEC/PDP评估曲线（原图）',image:'sec-pdp-decline-evaluation.png',q:13331,d:.176,
 annotations:'图中文字：递减率17.6%；起始点13331吨/月；PD：73.13万吨。另一个标注对平均产油曲线也采用17.6%。原图未明确递减率的时间口径与评估基准日。',
 petroleum:'历史绿色总产油相对平稳，而黄色井数总体增加、品红平均产油走低，提示新增开井可能掩盖单井产能衰减；蓝色产水上升提示水负荷增加，应核对同井组含水率、井龄和注采响应。以上是视觉趋势候选解释，未做像素取数，也没有压力证据。',
 conclusion:'优先把总量拆为在产井数×单井日产×开井天数，区分井数支撑与单井递减；补充含水、停井和压力资料后复核递减阶段。图上73.13万吨仅作为原图PD标注展示，不重新认定为本平台计算的PDP储量。'}
];
export function referenceProjection(q,d,years){return {year:years,base:q*(1-d)**years,low:q*(1-Math.min(.99,d+.02))**years,high:q*(1-Math.max(0,d-.02))**years};}
function chart(e){const rows=Array.from({length:61},(_,i)=>referenceProjection(e.q,e.d,i/12));const x=t=>60+t/5*620,y=q=>230-q/e.q*185,points=k=>rows.map(r=>`${x(r.year)},${y(r[k])}`).join(' ');return `<svg class="pdp-reference-chart" viewBox="0 0 720 290" role="img" aria-label="${e.title}：标注参数的五年条件外推与递减率敏感性带"><title>${e.title}：相对起点五年条件外推</title><rect x="60" y="35" width="620" height="195" fill="#fff" stroke="#ddd"/>${[0,.5,1].map(v=>`<line x1="60" x2="680" y1="${y(v*e.q)}" y2="${y(v*e.q)}" stroke="#eee"/><text x="52" y="${y(v*e.q)+4}" text-anchor="end">${num(v*e.q,0)}</text>`).join('')}<polygon points="${points('high')} ${[...rows].reverse().map(r=>`${x(r.year)},${y(r.low)}`).join(' ')}" fill="#d4e7db"/><polyline points="${points('base')}" fill="none" stroke="#2d8055" stroke-width="2.5"/>${[0,1,2,3,4,5].map(t=>`<text x="${x(t)}" y="250" text-anchor="middle">${t}年</text>`).join('')}<text x="60" y="22">月产油（吨/月）；相对原图标注起点</text><text x="60" y="277">绿线：标注递减率条件预测；浅绿带：递减率±2个百分点敏感性，非95%区间</text></svg>`;}
function card(e){return `<article class="panel pdp-panel pdp-reference-card"><div class="panel-head"><h3>${e.title}</h3><a class="btn small" href="assets/${e.image}" target="_blank" rel="noopener">查看原尺寸 ↗</a></div><div class="panel-body"><figure><a href="assets/${e.image}" target="_blank" rel="noopener"><img src="assets/${e.image}" alt="用户提供的${e.title}，含产油、平均产油、产水、井数及指数递减外推" loading="lazy" width="1142" height="760"></a><figcaption>${e.annotations}</figcaption></figure><div class="pdp-analysis-grid"><div><h4>石油专业解读</h4><p>${e.petroleum}</p></div><div><h4>概率统计解读</h4><p>半对数图上的近直线与指数递减相容，不能仅据视觉认定模型最优或统计显著。原图缺少逐月观测、残差、样本量与参数协方差，不能计算MAE、R²、p值或数据支持的95%置信/预测区间。井数、产水曲线使用不同纵轴，图形高度不能直接比较。</p></div></div><div class="note"><b>分析结论与下一步：</b>${e.conclusion}</div><h4>基于图中参数的条件预测（不是当前年月的现场预测）</h4><p>假设图中${num(e.d*100,1)}%为有效年递减率，生产制度与已有井条件不变，以标注${num(e.q,0)}吨/月为t=0；基准日未核实，不映射到当前日历年份。</p>${chart(e)}<div class="table-wrap"><table><thead><tr><th>距起点</th><th>基准预测 / 吨·月⁻¹</th><th>较快递减 / 吨·月⁻¹</th><th>较慢递减 / 吨·月⁻¹</th></tr></thead><tbody>${[1,2,3,5].map(t=>{const r=referenceProjection(e.q,e.d,t);return `<tr><td>${t}年</td><td>${num(r.base,0)}</td><td>${num(r.low,0)}</td><td>${num(r.high,0)}</td></tr>`;}).join('')}</tbody></table></div></div></article>`;}
export function renderPdpReferences(){return `<section class="pdp-references" aria-label="用户原图SEC与PDP评估样例"><div class="pdp-intro"><span class="section-label">SEC / PDP · ORIGINAL REFERENCE CASES</span><h2>SEC储量动态评估曲线 · 两幅原图样例</h2><p>来源：用户提供的新疆油田公司某区块评估截图（8553.PNG、8554.PNG），区块、日期及报告口径待原报告确认。完整保留原图，不将截图转换为伪造月报。下方分析与外推是本平台的研究解读，不代表原作者结论。</p></div>${examples.map(card).join('')}<section class="panel pdp-panel"><div class="panel-head"><h3>样例预测模型、结构与预警衔接</h3></div><div class="panel-body"><p><b>模型名称：</b>Arps指数递减的标注参数外推（无重新训练）。</p><div class="flow"><span>原图标注核对</span><span>→</span><span>有效年递减假设</span><span>→</span><span>条件外推与敏感性</span><span>→</span><span>补充月报后统计验证</span></div><code>Q(t)=Q₀(1−D)ᵗ = Q₀exp(−at)；a=−ln(1−D)\n敏感性下界：Q₀[1−(D+0.02)]ᵗ；上界：Q₀[1−(D−0.02)]ᵗ</code><p>Q₀：原图标注月产油（吨/月）；D：假设的有效年递减率；t：距起点年数；a：连续名义年递减系数（年⁻¹）。±2个百分点为展示者设定的敏感性扰动，没有概率含义。无训练/验证/测试集划分、无训练时长、无拟合精度分数，计算仅为代公式外推。</p><p><b>统计验证路径：</b>取得原始月报后，按时间顺序拟合稳定段并保留之后月份做滚动验证，检查残差相关性、异常工况和区间覆盖率；用参数/残差重采样估计均值CI与未来观测PI。下方交互工作台可上传月报与年末计划执行此流程；其默认生成数据结果与这两幅原图独立。</p><p><b>预警—专家研判：</b>冻结原年末计划 → 比较同口径月产偏差及预测区间 → 连续偏低/阈值触发 → 核实停井、含水、压力、计量与注采证据 → 输出带适用条件的恢复生产、控水诊断、能量核验或模型复评措施。原图本身不触发数值预警。</p><p class="tiny">储量还涉及经济极限、价格成本、权益与工程可采条件；仅积分外推曲线不能复现正式SEC/PDP评估。不得凭缺少证据的更有利递减形式上调储量。</p><div class="source-links"><a href="https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/oil-gas-rules" target="_blank" rel="noopener">SEC评估解释（154.01）</a><a href="https://itl.nist.gov/div898/handbook/pmd/section5/pmd512.htm" target="_blank" rel="noopener">NIST：未来观测预测区间</a></div></div></section></section>`;}
